  const P=[];titles.forEach((t,i)=>{const [cx,cy]=pos(i);const G=el('g',{},g);const fr=el('rect',{x:cx-W/2+8,y:cy-H/2,width:W-16,height:H,rx:16,fill:'#0D1B2A',stroke:TH.faint,'stroke-width':3},G);txt(G,T(t),cx,cy-H/2+30,{size:19,color:'ink',weight:800});P.push({G,fr,cx,cy:cy+15})});
  const cell=(G,x,y,rx,ry)=>el('ellipse',{cx:x,cy:y,rx,ry:ry||rx,fill:'#263238',stroke:'#B0BEC5','stroke-width':3,opacity:.9},G);
  const spind=(G,x,y,w,targets)=>{targets.forEach(([tx,ty])=>{el('line',{x1:x-w,y1:y,x2:tx,y2:ty,stroke:'#FFF59D','stroke-width':1.5,opacity:.5},G);el('line',{x1:x+w,y1:y,x2:tx,y2:ty,stroke:'#FFF59D','stroke-width':1.5,opacity:.5},G)});[x-w,x+w].forEach(px=>el('circle',{cx:px,cy:y,r:6,fill:'#FFF59D'},G))};
  // 0 interphase
  {const {G,cx,cy}=P[0];cell(G,cx,cy,150,120);el('circle',{cx,cy,r:95,fill:'none',stroke:'#78909C','stroke-width':2,'stroke-dasharray':'6 5'},G);dup(G,cx-50,cy-15,90,[R],[R]);dup(G,cx+40,cy+10,90,[B],[B]);dup(G,cx-10,cy+45,55,[r],[r]);dup(G,cx+60,cy-50,55,[b],[b])}
  // 1 prophase I
  {const {G,cx,cy}=P[1];cell(G,cx,cy,150,120);dup(G,cx-50,cy,100,LR1,LR2);dup(G,cx-26,cy,100,LB1,LB2);el('path',{d:`M${cx-44},${cy+10} L${cx-32},${cy+22} M${cx-32},${cy+10} L${cx-44},${cy+22}`,stroke:'#FFEB3B','stroke-width':3},G);dup(G,cx+40,cy,60,SR,SR);dup(G,cx+64,cy,60,SB,SB)}
  // 2 metaphase I
  {const {G,cx,cy}=P[2];cell(G,cx,cy,160,115);el('line',{x1:cx,y1:cy-100,x2:cx,y2:cy+100,stroke:'#78909C','stroke-width':2,'stroke-dasharray':'5 5'},G);spind(G,cx,cy,140,[[cx-20,cy-40],[cx+20,cy-40],[cx-20,cy+45],[cx+20,cy+45]]);dup(G,cx-20,cy-40,90,LR1,LR2);dup(G,cx+20,cy-40,90,LB1,LB2);dup(G,cx-20,cy+45,55,SB,SB);dup(G,cx+20,cy+45,55,SR,SR)}
  // 3 anaphase I
  {const {G,cx,cy}=P[3];cell(G,cx,cy,170,110);spind(G,cx,cy,150,[[cx-95,cy-35],[cx+95,cy-35],[cx-95,cy+45],[cx+95,cy+45]]);dup(G,cx-95,cy-35,90,LR1,LR2);dup(G,cx+95,cy-35,90,LB1,LB2);dup(G,cx-95,cy+45,55,SB,SB);dup(G,cx+95,cy+45,55,SR,SR)}
  // 4 telophase I
  {const {G,cx,cy}=P[4];[[cx-90,[LR1,LR2],[SB,SB]],[cx+90,[LB1,LB2],[SR,SR]]].forEach(([x,l,s])=>{cell(G,x,cy,82,105);dup(G,x-18,cy-15,90,...l);dup(G,x+28,cy+20,55,...s)})}
  // 5 metaphase II
  {const {G,cx,cy}=P[5];[[cx-90,[LR1,LR2],[SB,SB]],[cx+90,[LB1,LB2],[SR,SR]]].forEach(([x,l,s])=>{cell(G,x,cy,82,105);el('line',{x1:x,y1:cy-90,x2:x,y2:cy+90,stroke:'#78909C','stroke-width':2,'stroke-dasharray':'5 5'},G);dup(G,x,cy-35,80,...l);dup(G,x,cy+45,50,...s)})}
  // 6 anaphase II
