KIT.names(NAMES.en,{rs_gl:'Glycolysis (cytosol): glucose → 2 pyruvate',rs_pd:'Pyruvate dehydrogenase: → acetyl-CoA + CO₂',rs_kr:'Krebs cycle (matrix)',rs_etc:'Electron transport chain (inner membrane)',rs_as:'ATP synthase: H⁺ flow → ATP',rs_o2:'O₂ — final acceptor: O₂ + 4H⁺ + 4e⁻ → 2H₂O',rs_h:'H⁺ gradient (~200 mV)',rs_cy:'Cyanide blocks complex IV',rs_c1:'Complex I (NADH)',rs_c3:'Complex III',rs_c4:'Complex IV (cytochrome oxidase)',rs_q:'Ubiquinone (Q)',rs_cc:'Cytochrome c'});
