    const ac=box(g,700,560,240,70,T(U('2 Atsetil-KoA','2 Acetyl-CoA')),'#81C784',{size:20});arw(g,[395,560],[575,560],'#81C784',5);txt(g,'+2 NADH, 2 CO₂',485,600,{size:18,color:'#81C784',weight:800});
    const kc=[960,450];el('circle',{cx:kc[0],cy:kc[1],r:110,fill:'none',stroke:'#4FC3F7','stroke-width':8,'stroke-dasharray':'30 10'},g);txt(g,T(U('Krebs sikli ×2','Krebs cycle ×2')),kc[0],kc[1]-8,{size:22,color:'ink',weight:800});txt(g,'6 NADH · 2 FADH₂',kc[0],kc[1]+22,{size:17,color:'#4FC3F7',weight:800});txt(g,T(U('2 ATF(GTF) · 4 CO₂','2 ATP(GTP) · 4 CO₂')),kc[0],kc[1]+46,{size:17,color:'#4FC3F7',weight:800});arw(g,[820,540],[880,520],'#81C784',5);
